/**
 * Read an amount of bytes at a given offset, preferring data from the
 * copy-on-write diff file over data from the master file. Reads at
 * most one contiguous range of pages that are either all present in
 * the diff file or all absent from it, so that the caller can loop
 * over this function like it does over rawexpread().
 *
 * @param a The offset where the read should start
 * @param buf A buffer to read into
 * @param len The size of buf
 * @param client The client we're serving for
 * @return The number of bytes actually read, or -1 in case of an error
 **/
static ssize_t cow_read(off_t a, char *buf, size_t len, CLIENT *client) {
	uint64_t page = a / DIFFPAGESIZE;
	size_t pageoff = a % DIFFPAGESIZE;
	size_t chunk = len;
	gpointer value;
	bool dirty;
	ssize_t retval;

	if(chunk > DIFFPAGESIZE - pageoff)
		chunk = DIFFPAGESIZE - pageoff;

	pthread_rwlock_rdlock(&client->export_lock);
	dirty = g_hash_table_lookup_extended(client->diffpages, (gpointer)(uintptr_t)page, NULL, &value);
	/* Extend the read over subsequent pages that are in the same
	 * state, so that we don't need to switch files after every
	 * page. For pages in the diff file, they must also be
	 * contiguous in the diff file. */
	while(chunk < len) {
		uint64_t nextpage = (a + chunk) / DIFFPAGESIZE;
		gpointerv nextvalue;
		bool nextdirty = g_hash_table_lookup_extended(client->diffpages, (gpointer)(uintptr_t)nextpage, NULL, &nextvalue);
		if(nextdirty != dirty)
			break;
		if(dirty && (off_t)(uintptr_t)nextvalue != (off_t)(uintptr_t)value + (off_t)chunk)
			break;
		chunk += MIN(len - chunk, (size_t)DIFFPAGESIZE);
	}
	pthread_rwlock_unlock(&client->export_lock);

	if(dirty) {
		retval = 0;
		while(retval < (ssize_t)chunk) {
			ssize_t r = pread(client->difffile, buf + retval, chunk - retval, (off_t)(uintptr_t)value + pageoff + retval);
			if(r < 0)
				return -1;
			if(r == 0)
				break;
			retval += r;
		}
	} else {
		retval = rawexpread(a, buf, chunk, client);
	}
	return retval;
}
```

