/**
 * Support for copy-on-write exports.
 *
 * When an export is marked with the copyonwrite option, writes do not
 * go to the master file, but to a per-connection diff file which is
 * removed again when the client disconnects, discarding the writes.
 * The export is tracked in chunks of DIFFPAGESIZE bytes; chunks that
 * have been written are present in the diff file, everything else is
 * served from the master file.
 **/

/**
 * Check whether copy-on-write is active for this client.
 *
 * @param client The client we're serving for
 * @return true if writes should go to the copy-on-write diff file
 **/
static bool cow_active(CLIENT *client) {
	return client->difffile != -1;
}

/**
 * Read an amount of bytes from the copy-on-write diff file, retrying
 * until everything has been read.
 *
 * @param client The client we're serving for
 * @param buf A buffer to read into
 * @param len The size of buf
 * @param off The offset in the diff file where the read should start
 * @return 0 on success, -1 in case of an error
 **/
static int diff_read_fully(CLIENT *client, char *buf, size_t len, off_t off) {
	while(len > 0) {
		ssize_t ret = pread(client->difffile, buf, len, off);
		if(ret <= 0)
			return -1;
		buf += ret;
		off += ret;
		len -= ret;
	}
	return 0;
}

/**
 * Write an amount of bytes to the copy-on-write diff file, retrying
 * until everything has been written.
 *
 * @param client The client we're serving for
 * @param buf The buffer to write from
 * @param len The length of buf
 * @param off The offset in the diff file where the write should start
 * @return 0 on success, -1 in case of an error
 **/
static int diff_write_fully(CLIENT *client, const char *buf, size_t len, off_t off) {
	while(len > 0) {
		ssize_t ret = pwrite(client->difffile, buf, len, off);
		if(ret < 0)
			return -1;
		buf += ret;
		off += ret;
		len -= ret;
	}
	return 0;
}

/**
 * Read an amount of bytes at a given offset, serving data written
 * during this connection from the copy-on-write diff file and
 * everything else from the master file. Reads at most one range of
 * pages that are either all present in the diff file or all absent
 * from it, so the caller can loop over this function the same way it
 * loops over rawexpread().
 *
 * @param a The offset where the read should start
 * @param buf A buffer to read into
 * @param len The size of buf
 * @param client The client we're serving for
 * @return The number of bytes actually read, or -1 in case of an error
 **/
static ssize_t cow_read(off_t a, char *buf, size_t len, CLIENT *client) {
	uint64_t page = a / DIFFPAGESIZE;
	size_t pageoff = a % DIFFPAGESIZE;
	size_t chunk = MIN(len, (size_t)(DIFFPAGESIZE - pageoff));
	gpointer value;
	bool dirty;
	int ret;

	pthread_rwlock_rdlock(&client->export_lock);
	dirty = g_hash_table_lookup_extended(client->diffpages,
			(gpointer)(uintptr_t)page, NULL, &value);
	/* Extend the read over subsequent pages in the same state, so
	 * that we can serve it from one file. Pages in the diff file
	 * must also be contiguous in the diff file. */
	while(chunk < len) {
		uint64_t nextpage = (a + chunk) / DIFFPAGESIZE;
		gpointer nextvalue;
		bool nextdirty = g_hash_table_lookup_extended(client->diffpages,
				(gpointer)(uintptr_t)nextpage, NULL, &nextvalue);
		if(nextdirty != dirty)
			break;
		if(dirty && (off_t)(uintptr_t)nextvalue !=
				(off_t)(uintptr_t)value + (off_t)chunk)
			break;
		chunk += MIN(len - chunk, (size_t)DIFFPAGESIZE);
	}
	pthread_rwlock_unlock(&client->export_lock);

	DEBUG("(COW READ from %s offset %llu len %u), ",
			dirty ? "diff file" : "master file",
			(long long unsigned)a, (unsigned int)chunk);

	if(dirty) {
		if(diff_read_fully(client, buf, chunk,
				(off_t)(uintptr_t)value + pageoff) < 0)
			return -1;
		return chunk;
	}
	return master_expread(a, buf, chunk, client);
}
```

