/**
 * Write an amount of bytes at a given offset to the copy-on-write diff
 * file, leaving the master file alone. Pages written for the first
 * time are recorded so that reads can serve them from the diff file.
 * If a page is only partially written, the rest of the page is copied
 * from the master file first, so pages in the diff file are always
 * complete.
 *
 * @param a The offset where the write should start
 * @param buf The buffer to write from
 * @param len The length of buf
 * @param client The client we're serving for
 * @param fua Flag to indicate 'Force Unit Access'
 * @return The number of bytes actually written, or -1 in case of an error
 **/
static ssize_t cow_write(off_t a, char *buf, size_t len, CLIENT *client, int fua) {
	size_t done = 0;
	ssize_t retval = -1;

	pthread_rwlock_wrlock(&client->export_lock);
	while(done < len) {
		off_t off = a + done;
		uint64_t page = off / DIFFPAGESIZE;
		size_t pageoff = off % DIFFPAGESIZE;
		size_t chunk = MIN(len - done, (size_t)(DIFFPAGESIZE - pageoff));
		size_t pagesize = MIN((uint64_t)DIFFPAGESIZE, client->exportsize - page * DIFFPAGESIZE);
		gpointer value;
		off_t diffoff;

		DEBUG("(COW WRITE to diff file offset %llu len %u), ",
				(long long unsigned)off, (unsigned int)chunk);

		if(!g_hash_table_lookup_extended(client->diffpages,
				(gpointer)(uintptr_t)page, NULL, &value)) {
			if(client->server->flags & F_SPARSE) {
				diffoff = (off_t)(page * DIFFPAGESIZE);
			} else {
				/* map newly written pages to the end of the
				 * diff file */
				diffoff = client->diffend;
				client->diffend += pagesize;
			}
			if(chunk < pagesize) {
				/* Only part of the page is written; copy the
				 * rest of it from the master file so that it
				 * stays visible. */
				char pagebuf[DIFFPAGESIZE];
				size_t pagedone = 0;
				while(pagedone < pagesize) {
					ssize_t ret = master_expread((off_t)(page * DIFFPAGESIZE) + pagedone,
							pagebuf + pagedone, pagesize - pagedone, client);
					if(ret <= 0)
						goto out;
					pagedone += ret;
				}
				if(diff_write_fully(client, pagebuf, pagesize, diffoff) < 0)
					goto out;
			}
			g_hash_table_insert(client->diffpages,
					(gpointer)(uintptr_t)page,
					(gpointer)(uintptr_t)diffoff);
		} else {
			diffoff = (off_t)(uintptr_t)value;
		}
		if(diff_write_fully(client, buf + done, chunk, diffoff + pageoff) < 0)
			goto out;
		done += chunk;
	}
	if(client->server->flags & F_SYNC) {
		fsync(client->difffile);
	} else if(fua) {
		fdatasync(client->difffile);
	}
	retval = (ssize_t)done;
out:
	pthread_rwlock_unlock(&client->export_lock);
	return retval;
}
