/**
  * Set up the copy-on-write diff file for a client.
  *
  * Writes to a copy-on-write export go to a per-connection diff file
  * rather than to the master file. The diff file is created in the
  * directory configured with the cowdir option, or in the same
  * directory as the master file if that option is absent, and is
  * removed again when the client disconnects.
  *
  * @param client the CLIENT structure with .server and .exportsize set
  * up correctly
  * @return true on success, false otherwise
  */
static bool setup_cowfile(CLIENT* client) {
	_cleanup_g_free_ gchar *dir = NULL;
	_cleanup_g_free_ gchar *base = NULL;

	if(client->server->cowdir && *(client->server->cowdir)) {
		dir = g_strdup(client->server->cowdir);
	} else {
		dir = g_path_get_dirname(client->exportname);
	}
	base = g_path_get_basename(client->exportname);
	client->diffname = g_strdup_printf("%s/%s-%d.diff", dir, base, (int)getpid());
	DEBUG("Opening copy-on-write diff file %s\n", client->diffname);
	client->difffile = open(client->diffname, O_RDWR | O_CREAT | O_TRUNC, 0600);
	if(client->difffile == -1) {
		msg(LOG_ERR, "Could not open copy-on-write diff file %s: %m", client->diffname);
		g_free(client->diffname);
		client->diffname = NULL;
		return false;
	}
	if(client->server->flags & F_SPARSE) {
		/* In sparse mode, the diff file is as large as the export
		 * itself, and pages are written at their actual offset. */
		if(ftruncate(client->difffile, (off_t)client->exportsize) < 0) {
			msg(LOG_ERR, "Could not expand copy-on-write diff file %s: %m", client->diffname);
			close(client->difffile);
			client->difffile = -1;
			g_free(client->diffname);
			client->diffname = NULL;
			return false;
		}
	}
	client->diffpages = g_hash_table_new(NULL, NULL);
	msg(LOG_INFO, "Copy-on-write enabled, diff file is %s", client->diffname);
	return true;
}

