 * @param len The size of buf
 * @param client The client we're serving for
 * @return The number of bytes actually read, or -1 in case of an error
 **/
static ssize_t cow_read(off_t a, char *buf, size_t len, CLIENT *client) {
	uint64_t page = a / DIFFPAGESIZE;
	size_t pageoff = a % DIFFPAGESIZE;
	size_t chunk = MIN(len, (size_t)(DIFFPAGESIZE - pageoff));
	gpointer value;
	bool dirty;

	pthread_rwlock_rdlock(&client->export_lock);
	dirty = g_hash_table_lookup_extended(client->diffpages,
			(gpointer)(uintptr_t)page, NULL, &value);
	/* Extend the read over subsequent pages in the same state, so
	 * that it can be served from one file. Pages in the diff file
	 * must also be contiguous in the diff file. */
	while(chunk < len) {
		uint64_t nextpage = (a + chunk) / DIFFPAGESIZE;
		gpointer nextvalue;
		bool nextdirty = g_hash_table_lookup_extended(client->diffpages,
				(gpointer)(uintptr_t)nextpage, NULL, &nextvalue);
		if(nextdirty != dirty)
			break;
		if(dirty && (off_t)(uintptr_t)nextvalue !=
				(off_t)(uintptr_t)value + (off_t)chunk)
			break;
		chunk += MIN(len - chunk, (size_t)DIFFPAGESIZE);
	}
	pthread_rwlock_unlock(&client->export_lock);

	DEBUG("(COW READ from %s offset %llu len %u), ",
	      dirty ? "diff file" : "master file",
	      (long long unsigned)a, (unsigned int)chunk);

	if(dirty) {
		if(diff_read_fully(client, buf, chunk,
					(off_t)(uintptr_t)value + pageoff) < 0)
			return -1;
		return chunk;
	}
	return master_expread(a, buf, chunk, client);
